Account.ready.then(async user=>{
 const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x};
 const modeNames={exam:'Exam',reviewer:'Review',case_scenarios:'Case scenarios'};
 $('welcome').textContent='Welcome back, '+user.name;if(['admin','editor'].includes(user.role)){$('access-note').hidden=false;$('access-note').textContent=(user.role==='editor'?'Editor access':'Admin preview')+' · Draft questions are included.';}
 function sync(){const mode=$('session-mode');for(const b of document.querySelectorAll('[data-mode]')){const option=[...mode.options].find(o=>o.value===b.dataset.mode);b.disabled=!!option?.disabled;b.setAttribute('aria-pressed',String(mode.value===b.dataset.mode));b.title=b.disabled?'No questions available for this subject and topic.':'';}const list=$('collection-shortcuts');list.replaceChildren();for(const c of Collections.read()){const b=el('button',undefined,'collection-shortcut');b.type='button';b.setAttribute('aria-pressed',String($('set-collection').value===c.id));const text=el('span');const option=[...$('set-collection').options].find(o=>o.value===c.id);const n=option?.textContent.match(/\((\d+)\)$/)?.[1];text.append(el('strong',c.name),el('small',(n??c.questions.length)+' questions available'));b.append(text,el('span','›'));b.onclick=()=>{$('set-collection').value=c.id;$('set-collection').dispatchEvent(new Event('change'));$('start-set').focus()};list.append(b)}}
 for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>{if(b.disabled)return;$('session-mode').value=b.dataset.mode;$('session-mode').dispatchEvent(new Event('change'));sync()};
 window.addEventListener('learning-selection-changed',sync);window.addEventListener('collections-changed',sync);$('new-collection-toggle').onclick=()=>{$('collection-create-panel').open=!$('collection-create-panel').open;if($('collection-create-panel').open)$('new-collection-name').focus()};$('collection-create-panel').ontoggle=()=>$('new-collection-toggle').setAttribute('aria-expanded',String($('collection-create-panel').open));sync();
 const date=v=>new Date(v).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});
 function title(a){const topics=[...new Set(a.questions.map(q=>q.topic).filter(Boolean))];return topics.length===1?topics[0]:'Mixed topics';}
 try{const attempts=await Account.request('/api/attempts');const finished=attempts.filter(a=>a.result).sort((a,b)=>Date.parse(b.submitted)-Date.parse(a.submitted));$('completed-count').textContent=finished.length+' session'+(finished.length===1?'':'s')+' completed';const unfinished=attempts.filter(a=>!a.result).sort((a,b)=>Date.parse(b.started)-Date.parse(a.started))[0];
 if(unfinished){try{const a=await Account.request('/api/attempt?id='+encodeURIComponent(unfinished.id));const box=$('continue-learning'),info=el('div');const answered=(a.draft?.answers||[]).filter(v=>Array.isArray(v)?v.length>0:String(v??'').trim()!=='').length;info.append(el('p','CONTINUE LEARNING','eyebrow'),el('h2',title(a)),el('p',modeNames[a.mode]+' · '+answered+' of '+a.questions.length+' answered · Started '+date(a.started)));const progress=el('progress');progress.max=a.questions.length;progress.value=answered;progress.setAttribute('aria-label','Questions answered');info.append(progress);const resume=el('a','Resume '+(a.mode==='exam'?'exam':a.mode==='reviewer'?'review':'scenarios'),'primary');resume.href='/?set=1&attempt='+encodeURIComponent(a.id);box.replaceChildren(info,resume);box.hidden=false;}catch(e){$('activity-status').textContent='Could not load your unfinished session. Open My attempts to resume.';const link=el('a',' My attempts');link.href='/history.html';$('activity-status').append(link)}}
 const body=$('recent-attempts');body.replaceChildren();if(!finished.length){const row=el('tr'),cell=el('td','Your completed sessions will appear here.');cell.colSpan=5;row.append(cell);body.append(row)}
 for(const a of finished.slice(0,3)){let label=a.questions+' questions';try{label=title(await Account.request('/api/attempt?id='+encodeURIComponent(a.id)))}catch{}const row=el('tr');for(const value of [label,modeNames[a.mode],date(a.submitted)])row.append(el('td',value));const score=el('td');score.append(el('span',a.result.total+' / '+a.result.maximum,'score-pill'));const report=el('td'),link=el('a','View report');link.href='/history.html?attempt='+encodeURIComponent(a.id);report.append(link);row.append(score,report);body.append(row)}
 }catch(e){$('activity-status').textContent='Your activity could not be loaded. Refresh to try again.';$('recent-attempts').replaceChildren();const tr=el('tr'),td=el('td','Attempt history is temporarily unavailable.');td.colSpan=5;tr.append(td);$('recent-attempts').append(tr);}
}).catch(()=>{});
